## 2. Pruebas Unitarias e Integración (Vitest)

Validamos la lógica de negocio offline-first con IndexedDB y la consistencia matemática del recaudo mixto frente a los totales con impuestos.

```typescript
// src/__tests__/spec-043-recaudo-preventa.test.ts
import { describe, it, expect, beforeEach } from 'vitest';
import { preventaMasterSchema, preventaItemSchema, recaudoMixtoSchema } from '../schemas/spec-043';

describe('SPEC-043: Validación de Preventas y Recaudo Mixto', () => {

  const mockTenantId = "a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11";
  const mockClienteId = "b1eebc99-9c0b-4ef8-bb6d-6bb9bd380a22";
  const mockVendedorId = "c2eebc99-9c0b-4ef8-bb6d-6bb9bd380a33";
  const mockProductoId = "d3eebc99-9c0b-4ef8-bb6d-6bb9bd380a44";

  it('Debe validar correctamente un ítem con nota de preventa', () => {
    const itemValido = {
      id: "e4eebc99-9c0b-4ef8-bb6d-6bb9bd380a55",
      tenant_id: mockTenantId,
      producto_id: mockProductoId,
      vendedor_id: mockVendedorId,
      cantidad: 5,
      precio_unitario: 12000,
      impuesto_iva: 19,
      nota_linea: "Cortar a 2.5 metros según solicitud del maestro de obra"
    };

    const resultado = preventaItemSchema.safeParse(itemValido);
    expect(resultado.success).toBe(true);
  });

  it('Debe rechazar notas de línea que excedan los 250 caracteres', () => {
    const itemInvalido = {
      id: "e4eebc99-9c0b-4ef8-bb6d-6bb9bd380a55",
      tenant_id: mockTenantId,
      producto_id: mockProductoId,
      vendedor_id: mockVendedorId,
      cantidad: 1,
      precio_unitario: 5000,
      impuesto_iva: 19,
      nota_linea: "A".repeat(251) // Excede límite
    };

    const resultado = preventaItemSchema.safeParse(itemInvalido);
    expect(resultado.success).toBe(false);
  });

  it('Debe validar la distribución de recaudo mixto correctamente', () => {
    const recaudo = {
      efectivo: 50000,
      tarjeta: 100000,
      transferencia: 0,
      credito: 25000
    };

    const resultado = recaudoMixtoSchema.safeParse(recaudo);
    expect(resultado.success).toBe(true);
  });

  it('Debe fallar si el recaudo mixto total es cero', () => {
    const recaudoVacio = {
      efectivo: 0,
      tarjeta: 0,
      transferencia: 0,
      credito: 0
    };

    const resultado = recaudoMixtoSchema.safeParse(recaudoVacio);
    expect(resultado.success).toBe(false);
    if (!resultado.success) {
      expect(resultado.error.errors[0].message).toContain("El recaudo total mixto debe ser mayor a 0");
    }
  });

});
