## 3. Pruebas End-to-End (Playwright)

Validamos el flujo completo en la interfaz de usuario: ingreso masivo en IndexedDB por múltiples vendedores, adición de notas personalizadas y procesamiento de pago mixto con salida a Facturación DIAN.

```typescript
// e2e/spec-043-multivendedor-josase.spec.ts
import { test, expect } from '@playwright/test';

test.describe('SPEC-043: Flujo E2E Ferretería Josase Multivendedor', () => {

  test.beforeEach(async ({ page }) => {
    // Simular inicio de sesión con Tenant RLS activo
    await page.goto('/login');
    await page.fill('input[name="email"]', 'vendedor1@ferreteriajosase.com');
    await page.fill('input[name="password"]', 'PasswordSeguro123*');
    await page.click('button[type="submit"]');
    await expect(page).toHaveURL('/dashboard');
  });

  test('De permitir preventa offline masiva en IndexedDB, agregar notas y ejecutar recaudo mixto', async ({ page }) => {
    // 1. Navegar al módulo de Preventas Multivendedor
    await page.click('text=Preventas / POS');
    await expect(page.locator('h1')).toContainText('Terminal de Preventas');

    // 2. Simular desconexión de red para verificar IndexedDB masivo
    await page.context().setOffline(true);

    // 3. Agregar múltiples productos al carrito
    await page.fill('input[placeholder="Buscar producto..."]', 'Varilla Corrugada');
    await page.click('text=Varilla Corrugada 3/8');

    // 4. Agregar nota específica a la línea del producto
    await page.click('button:has-text("Agregar Nota")');
    await page.fill('textarea[name="nota_linea"]', 'Entregar en bodega norte sin rayones');
    await page.click('button:has-text("Guardar Nota")');

    // 5. Verificar persistencia local en IndexedDB
    const countIndexedDB = await page.evaluate(async () => {
      return new Promise((resolve) => {
        const request = indexedDB.open('maestro_erp_offline', 1);
        request.onsuccess = (event: any) => {
          const db = event.target.result;
          const transaction = db.transaction(['preventas_locales'], 'readonly');
          const store = transaction.objectStore('preventas_locales');
          const countRequest = store.count();
          countRequest.onsuccess = () => resolve(countRequest.result);
        };
      });
    });
    expect(countIndexedDB).toBeGreaterThanOrEqual(1);

    // 6. Reconectar red para sincronización
    await page.context().setOffline(false);
    await page.click('button:has-text("Sincronizar Preventas")');
    await expect(page.locator('.sync-status-badge')).toContainText('Sincronizado');

    // 7. Proceder al Recaudo Mixto
    await page.click('button:has-text("Proceder al Pago")');
    await expect(page.locator('h2')).toContainText('Caja y Recaudo Mixto');

    // Distribuir pagos
    await page.fill('input[name="pago_efectivo"]', '50000');
    await page.fill('input[name="pago_tarjeta"]', '100000');
    await page.fill('input[name="pago_transferencia"]', '25000');

    // 8. Finalizar y Emitir Factura DIAN
    await page.click('button:has-text("Procesar y Facturar DIAN")');

    // 9. Aserción de éxito tributario DIAN
    await expect(page.locator('.dian-response-success')).toBeVisible({ timeout: 10000 });
    await expect(page.locator('.dian-cufe')).not.toBeEmpty();
  });

});
```

